let activeCoordinationForThread = (_threadId: string): boolean => false;
let liveStatusLine = (_threadId: string): string | undefined => undefined;
const wireTask = (task: TaskRecord, botModel: ModelSelection): WireTask => {
  const { snoozedUntil, ...base } = toWireTask(task, botModel, store.bots);
  const statusLine = liveStatusLine(task.threadId);
  const coordinated = { ...base, waitingForTeammates: activeCoordinationForThread(task.threadId) && !task.busy, ...(statusLine ? { statusLine } : {}) };
  const asleep = snoozedUntil === 0 || (snoozedUntil !== undefined && snoozedUntil > Date.now());
  return asleep ? { ...coordinated, snoozedUntil } : coordinated;
};

const wireBot = (bot: BotRecord): WireBot => {
  const { resumeCursors: _resumeCursors, tasks, approvalGrant, lastProfileRequestId: _lastProfileRequestId, packageBase: _packageBase, assignedSkills: _assignedSkills, ...rest } = bot;
  const visible = approvalGrant && !approvalGrant.threadOnly
    ? { ...rest, approvalMode: "ask" as const, autoApprove: false }
    : rest;
  return { ...visible, waitingForTeammates: activeCoordinationForThread(bot.threadId) && !threadBusy(bot.id, bot.threadId),
    avatarUrl: visible.avatarUrl ?? null, ...(tasks ? { tasks: tasks.map((task) => wireTask(task, bot.modelSelection)) } : {}) };
};

function toolScopeForTurn(botId: string) {
  const bot = store.bot(botId);
  if (!bot) throw Object.assign(new Error("no such bot"), { status: 404 });
  const parsed = parseToolScope(bot.toolScope);
  if (!parsed.ok) throw Object.assign(new Error("This dog's tool selection is invalid. Open Access settings and save a valid selection before starting a turn."), { status: 409, code: "tool_scope" });
  return parsed.scope;
}

const wireTrustedApprovalBot = (bot: NonNullable<ReturnType<typeof store.bot>>) => {
  const { resumeCursors: _resumeCursors, tasks, approvalGrant: _approvalGrant, lastProfileRequestId: _lastProfileRequestId, packageBase: _packageBase, assignedSkills: _assignedSkills, ...rest } = bot;
  return { ...rest, approvalMode: approvalModeFor(rest), avatarUrl: rest.avatarUrl ?? null, ...(tasks ? { tasks: tasks.map((task) => wireTask(task, bot.modelSelection)) } : {}) };
};

function previewSystemPrompt(bot: BotRecord) {
  const persona = [
    `You are ${bot.name}, a personal bot in later.dog.`,
    bot.title && `Role: ${bot.title}.`,
    bot.description && `About: ${bot.description}`,
  ]
    .filter(Boolean)
    .join(" ");
  const instance = registry.get(bot.modelSelection.instanceId);
  const caps = instance?.adapter.capabilities;
  const previewComputer = bot.computer;
  const computerPromptKind = resolveComputerPromptKind(previewComputer === "cloud"
    ? bot.cloudBackend === "vps" ? "vps" : "box" : previewComputer === "local" ? "local" : null);
  const peers = reachablePeers(store.bots, bot);
  const coordination = withMainDogRouting(bot.id === store.mainBotId(), peers.length > 0 ? PEERS_PROMPT : "");
  const agentsMounted = caps?.agentsMcp === true;
  const previewPlan = resolveSurface({
    destination: previewComputer,
    browserOn: caps?.browserMcp === true && builtInBrowserEnabled(cfg) && bot.browser !== false,
  });
  const privateWorkspace = instance && supportsWorkspaceFiles(instance.driverKind);
  const built = buildSystemPrompt(persona, bot.soul ?? "", [
    { id: "computer", label: "Computer", text: computerPrompt(computerPromptKind) },
    { id: "plan", label: "Surface", text: previewPlan.computer === undefined ? "" : surfacePrompt({
      computer: previewPlan.computer && previewPlan.computer !== "off" && computerPromptKind ? previewPlan.computer : null,
      browser: previewPlan.computer === undefined ? false : previewPlan.browser,
    }, { note: previewPlan.note, cloudHome: Boolean(CLOUD_HOME) }) },
    { id: "cloud-home", label: "My Cloud", text: CLOUD_HOME ? cloudHomePrompt(agentsMounted && lendingEnabled()) : "" },
    { id: "composio", label: "Connected apps", text: caps?.composioMcp && bot.composio !== false && composio.configured(cfg) ? composioSystemPrompt(bot.connectorTools) : "" },
    { id: "mcp", label: "MCP servers", text: caps?.customMcp ? customMcpPrompt(Object.keys(engineMcpServers(bot, connectedRepositories.known()))) : "" },
    { id: "browser", label: "Browser", text: previewPlan.browser ? BUILT_IN_BROWSER_SYSTEM_PROMPT : "" },
    { id: "coordination", label: "Team", text: agentsMounted && coordination ? ` ${coordination}` : "" },
    { id: "credential", label: "Credentials", text: agentsMounted ? CREDENTIAL_PROMPT : "" },
    { id: "routine", label: "Routines", text: agentsMounted ? ROUTINE_PROMPT : "" },
    { id: "profile", label: "Profile changes", text: agentsMounted ? PROFILE_PROMPT : "" },
    { id: "updates", label: "Progress updates", text: workUpdatesPrompt() },
    { id: "memory", label: "Memory", text: memorySystemPrompt(bot.id, { managedWrites: agentsMounted, fileTools: Boolean(privateWorkspace), enabled: bot.memoryEnabled !== false }) },
    { id: "skills", label: "Skills index", text: privateWorkspace ? skillsSystemPrompt(bot.id, skillsLibraryEnabled(cfg) ? bot.assignedSkills : undefined) : "" },
  ], cfg.profile?.name);
  const totalBytes = built.sections.reduce((n, s) => n + s.bytes, 0);
  return {
    sections: built.sections,
    totalBytes,
    approxTokens: Math.ceil(totalBytes / 4),
    note:
      "Preview from the dog's current settings, not the exact prompt of a running task. Task folders, notes, recall, selected tricks and available connections can change the dispatched prompt. Token count is an estimate.",
  };
}

